INSERT INTO reviews (id, author, company, location, rating, comment, project_type, status, verified, data) VALUES ('rev-1', NULL, NULL, 'Ludhiana, Punjab', 5, 'Ordered D27.9 protective lenses and D28 double nozzles for our RayTools BM110 3kW machine. Received genuine optics next morning via express delivery. Exceptional quality, zero spatter burn!', 'RayTools Lenses & Nozzles', 'approved', 1, '{"id":"rev-1","clientName":"Vikramjit Singh","companyName":"Punjab Heavy Fab & Engineering","location":"Ludhiana, Punjab","rating":5,"date":"2 days ago","comment":"Ordered D27.9 protective lenses and D28 double nozzles for our RayTools BM110 3kW machine. Received genuine optics next morning via express delivery. Exceptional quality, zero spatter burn!","projectType":"RayTools Lenses & Nozzles","verified":true}');
