INSERT INTO reviews (id, author, company, location, rating, comment, project_type, status, verified, data) VALUES ('rev-3', NULL, NULL, 'Rajkot, Gujarat', 5, 'High quality tellurium copper single and double chrome nozzles with perfect concentricity. Our fiber laser cutting consistency improved immediately, and express delivery arrived in 24 hours.', 'Tellurium Copper Laser Nozzles', 'approved', 1, '{"id":"rev-3","clientName":"Suresh Patel","companyName":"Gujarat Agro Implements","location":"Rajkot, Gujarat","rating":5,"date":"2 weeks ago","comment":"High quality tellurium copper single and double chrome nozzles with perfect concentricity. Our fiber laser cutting consistency improved immediately, and express delivery arrived in 24 hours.","projectType":"Tellurium Copper Laser Nozzles","verified":true}');
INSERT INTO reviews (id, author, company, location, rating, comment, project_type, status, verified, data) VALUES ('rev-4', NULL, NULL, 'Coimbatore, Tamil Nadu', 5, 'Ordered OSPRI LC80 protective windows and SMC ITV proportional valve. Genuine parts that resolved our gas pressure fluctuations immediately. Highly recommended!', 'OSPRI Spares & SMC Valves', 'approved', 1, '{"id":"rev-4","clientName":"Karthik Raja","companyName":"NKL Tech Fabricators","location":"Coimbatore, Tamil Nadu","rating":5,"date":"3 weeks ago","comment":"Ordered OSPRI LC80 protective windows and SMC ITV proportional valve. Genuine parts that resolved our gas pressure fluctuations immediately. Highly recommended!","projectType":"OSPRI Spares & SMC Valves","verified":true}');
